// static
bool UnionTraits<::blink::mojom::blink::WebViewMediaIntegrityTokenResponse::DataView, ::blink::mojom::blink::WebViewMediaIntegrityTokenResponsePtr>::Read(
    ::blink::mojom::blink::WebViewMediaIntegrityTokenResponse::DataView input,
    ::blink::mojom::blink::WebViewMediaIntegrityTokenResponsePtr* output) {
  using UnionType = ::blink::mojom::blink::WebViewMediaIntegrityTokenResponse;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kErrorCode: {
      ::blink::mojom::blink::WebViewMediaIntegrityErrorCode result_error_code;
      if (!input.ReadErrorCode(&result_error_code))
        return false;

      *output = UnionType::NewErrorCode(result_error_code);
      break;
    }
    case Tag::kToken: {
      ::blink::String result_token{};
      if (!input.ReadToken(&result_token))
        return false;

      *output = UnionType::NewToken(
          std::move(result_token));
      break;
    }
    default:

      return false;
  }
  return true;
}

